# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('denarius','/dɪˈnɑːriəs/','古罗马第纳里银币','名称保留了最初按十个较小单位计值的痕迹。','拉丁 deni 每十个 → denarius 含十个的；denarius nummus 这一钱币名称简化为 denarius，后借入英语。',[['拉丁 decem → deni → denarius','十 → 每十个 → 含十个的'],['拉丁钱币名 denarius → 英语 denarius','古罗马银币名称']],'在博物馆、罗马史或古代交易的文章里，它是一个具体币名。名字中的十反映早期计值背景，不代表这枚币在整个历史上永远等于十个固定单位，更不能拿它直接换算今天的钱。','a Roman denarius；a silver denarius；a collection of denarii。','denarius 是古代具体币名，money 是钱的泛称。常见复数 denarii 保留拉丁词尾，读到复数也仍是同一币种。',('The museum displayed a denarius beside a map of the Roman Empire.','博物馆在罗马帝国地图旁展出了一枚第纳里银币。'),('The collector compared two denarii from different reigns.','收藏者比较了两个不同统治时期的第纳里银币。'),sources=['https://www.etymonline.com/word/denarius','https://en.wiktionary.org/wiki/denarius#English']),
E('dinar','英 /ˈdiːnɑː/；美 /ˈdiːnɑːr/','第纳尔〔货币单位〕','古代币名沿不同语言传下去，成为后来一些货币的名称。','英语借入阿拉伯语 dinar 等形式；其主要历史路线经希腊 denarion 追到拉丁 denarius，某些地区的英语用法也经当地语言传入。',[['拉丁 denarius → 希腊 denarion → 阿拉伯 dinar','古罗马币名 → 传播中的币名'],['英语 dinar','第纳尔，指相关国家的货币单位']],'读价格或旅行材料时，dinar 是货币名称，不是金额本身；前面的数词才告诉你多少。不同地方都可能使用这个名字，不能因为名称相同，就把价值、发行单位和兑换关系看成一样。','pay in dinars；a dinar coin；prices quoted in dinars。','dinar 与 denarius 有历史联系，但不是说今天的第纳尔就是古罗马银币。dollar 与 dinar 也不能只按首字母联成同一词源。',('The guide explained why the prices on the menu were listed in dinars.','导游解释了菜单价格为什么以第纳尔标示。'),('She kept a dinar coin as a souvenir from the trip.','她留了一枚第纳尔硬币作为旅行纪念。'),sources=['https://www.etymonline.com/word/dinar','https://en.wiktionary.org/wiki/dinar#English']),
E('dinero','英 /dɪˈneərəʊ/；美 /dɪˈneroʊ/','钱〔口语、俚语〕','换个带西班牙语色彩的说法来谈钱。','英语借自西班牙 dinero 钱、硬币，远接拉丁 denarius 古罗马币名。具体币名逐渐能够泛指钱财，再被英语借来作较随意的表达。',[['拉丁 denarius → 西班牙 dinero','币名 → 硬币、钱'],['英语 dinero','口语中的钱；历史语境也可见具体币名用法']],'在英语里说 need more dinero，语气通常比 need more money 随意，有时带玩笑感。不要因为它来自一个币名，就把现代英语里每一次 dinero 都理解成某种法定货币。正式预算或合同通常直接用 money、funds 或具体币名。','enough dinero；save some dinero；need more dinero。','dinar 常是货币单位名称；dinero 在英语口语中通常泛指钱。它与 diner 餐馆、用餐者只有拼写接近，不能混记。',('I’d love a longer holiday, but I need more dinero first.','我也想多休几天假，不过得先多攒点钱。'),('He joked that the fancy coffee shop was taking all his dinero.','他开玩笑说，那家精致咖啡店快把他的钱全赚走了。'),sources=['https://www.merriam-webster.com/dictionary/dinero','https://en.wiktionary.org/wiki/dinero#English']),
E('denier','计量义英 /ˈdeniə/、美 /ˈdenjər/；否认者 /dɪˈnaɪə(r)/','旦〔纤维线密度单位〕；古钱币名；另源：否认者','同样长的一段丝线，称一称有多重；数字用来描述线的粗细程度。','钱币与计量义经法语 denier 追到拉丁 denarius；纺织用途沿用这一名称。否认者义则是英语 deny + -er 的独立构词，词源和读音都不同。',[['拉丁 denarius → 法语 denier → 英语 denier','古钱币名；后来也用于计量名称'],['纺织用法 denier','每 9000 米丝线以克计的质量数值'],['另源：英语 deny + -er → denier','否认某事的人']],'丝袜、纱线上的 denier 数字，严格说是线密度：9000 米线重多少克，就是多少旦。同类材料下数字高通常更粗，但它不是直接量直径，也不能单靠它决定成品的厚度和透明度。另一个读作“迪奈尔”的 denier 是否认者，与丝线无关。','the denier of a yarn；a lower denier；a denier of an established fact。','纺织 denier 与否认者 denier 是同形另源。前者常重读开头，后者重读 deny 对应的中段；不要把纺织数字解释成否认程度。',('The label gives the denier of the yarn used in the tights.','标签标出了这双连裤袜所用纱线的旦数。'),('For similar fibres, a higher denier means more mass for the same length.','对于相似纤维，旦数更高意味着相同长度的质量更大。'),('The article describes him as a persistent denier of the evidence.','文章把他描述为一个一直否认证据的人。'),sources=['https://www.etymonline.com/word/denier','https://www.merriam-webster.com/dictionary/denier','https://en.wiktionary.org/wiki/denier#English'])]
ROOT=dict(id='C0314',meaning='每十个；按十计',core='DEN = TEN EACH',image='先把十个单位算成一个币值，再看币名怎样走进不同语言和计量名称。',intro='拉丁 deni 表示每十个，来自十的词族；denarius 是含十个的，后来成了钱币名。英语相关词主要通过不同语言借入币名，并不是现代见到 den- 就可以机械算十。',forms='deni → denarius；经法语形成 denier，经希腊与阿拉伯等路线形成 dinar，经西班牙语形成 dinero。英语 den 狼窝不属于这条直接构词线。',branches=[['古代币名','denarius'],['货币名称与泛指钱','dinar；dinero'],['古币名延伸到计量','denier']],contrasts='相同历史币名不保证后来货币等值；denier 的否认者义又是另一词源。数字、币名、普通的钱和纺织计量，要靠语境区分。',practice='A denarius is an ancient coin; dinero can simply mean money in informal English.\n\ndenarius 是古币名；dinero 在英语口语中可以只是钱的意思。',words=[x['word'] for x in W],exclude={w:'较地域化的币名或冷门十数词，先保留常见阅读所需的几条支线。' for w in ['denar','dinheiro','denarian','denary']})
if __name__=='__main__':
 for name,data in [('roots_den',[ROOT]),('words_den',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
